#!/usr/bin/env node
// Phase 21D-B — real-Chromium certification of the WebGL mesh viewer (browser-harness/mesh-models-21db.*), WebGL 2 through ANGLE /
// SwiftShader (no GPU needed). The ENGINEERING test assembly is generated by the same deterministic writer the harness uses, and served
// at the code-derived same-origin URLs (/mesh-assets/<sha256>.glb and /api/mesh-assets/runtime/<sha256>) with a real streamed body.
// Pixel probes read the real WebGL image: depth buffering (the front block hides the back plate; hiding it reveals the plate; turning the
// model round puts the plate in front), the selection highlight, review marks; GPU picking selects the FRONT-MOST part; rotate / zoom /
// reset / touch / keyboard through the shared 21D orbit controller; MSAA and high-DPI buffers; context loss → automatic restore; 20 mount /
// unmount cycles leave no live renderer; integrity mismatch and missing labelled parts are refused with meaningful errors; the WebGL-
// unavailable fallback keeps the parts list usable; RTL page, no horizontal overflow on a phone, no page error, no external host.
import fs from "node:fs";
import http from "node:http";
import path from "node:path";
import crypto from "node:crypto";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { build } from "vite";
import { testAssemblyModel, writeGlb } from "../src/meshModels/glbWriter.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = path.resolve(process.env.HARNESS_OUT || path.join(root, ".harness-21db"));
const checks = [];
const check = (name, ok, detail = "") => { checks.push({ name, ok: !!ok, detail }); console.log((ok ? "PASS" : "FAIL") + " " + name + " " + detail); };
let chromium;
try { ({ chromium } = createRequire(path.join(process.env.PLAYWRIGHT_CORE_DIR || root, "package.json"))("playwright-core")); }
catch { console.error("playwright-core unavailable"); process.exit(2); }

const glb = Buffer.from(writeGlb(testAssemblyModel()));
const sha = crypto.createHash("sha256").update(glb).digest("hex");
const altSha = crypto.createHash("sha256").update(Buffer.from(writeGlb({ ...testAssemblyModel(), generator: "ExamBank test assembly (substituted)" }))).digest("hex");
fs.rmSync(out, { recursive: true, force: true });
await build({ configFile: path.join(root, "vite.config.ts"), root, logLevel: "warn", build: { outDir: out, emptyOutDir: true, rollupOptions: { input: path.join(root, "browser-harness/mesh-models-21db.html") } } });
const MIME = { ".js": "text/javascript", ".html": "text/html; charset=utf-8", ".css": "text/css", ".svg": "image/svg+xml", ".woff2": "font/woff2" };
let assetRequests = 0;
const server = http.createServer((req, res) => {
  const u = new URL(req.url, "http://localhost");
  // the asset routes: the genuine bytes for the pinned hash; for the "substituted" hash the server returns DIFFERENT bytes (integrity test)
  const m = u.pathname.match(/^\/mesh-assets\/([0-9a-f]{64})\.glb$/) || u.pathname.match(/^\/api\/mesh-assets\/runtime\/([0-9a-f]{64})$/);
  if (m) {
    assetRequests++;
    if (m[1] !== sha && m[1] !== altSha) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { "content-type": "model/gltf-binary", "content-length": String(glb.length), "x-content-type-options": "nosniff", "cache-control": "no-store" });
    // streamed in chunks (progress events)
    let o = 0;
    const pump = () => { if (o >= glb.length) { res.end(); return; } res.write(glb.subarray(o, o + 8192)); o += 8192; setTimeout(pump, 2); };
    pump();
    return;
  }
  const full = path.resolve(out, "." + decodeURIComponent(u.pathname));
  if (!full.startsWith(out + path.sep) || !fs.existsSync(full) || !fs.statSync(full).isFile()) { res.writeHead(404); res.end("not found"); return; }
  res.writeHead(200, { "content-type": MIME[path.extname(full)] || "application/octet-stream", "cache-control": "no-store" }); fs.createReadStream(full).pipe(res);
});
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
const origin = "http://127.0.0.1:" + server.address().port;
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH || undefined, headless: true, args: ["--no-sandbox", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
const errors = [], foreign = [];
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function open({ width = 1280, height = 900, query = "", touch = false, scale = 1 } = {}) {
  const page = await browser.newPage({ viewport: { width, height }, hasTouch: touch, isMobile: touch, deviceScaleFactor: scale });
  page.on("pageerror", e => errors.push(String(e)));
  page.on("console", m => { if (m.type() === "error") errors.push("console: " + m.text() + (m.location()?.url ? " @ " + m.location().url : "")); });
  page.on("response", r => { if (r.status() >= 400) errors.push("HTTP " + r.status() + " " + r.url()); });
  page.on("request", r => { const u = new URL(r.url()); if (u.origin !== origin && u.protocol !== "data:" && u.protocol !== "blob:") foreign.push(r.url()); });
  const t0 = Date.now();
  await page.goto(origin + "/browser-harness/mesh-models-21db.html" + query, { waitUntil: "load" });
  return { page, t0 };
}
const sel = s => "[data-testid=sec-" + s + "] .mm3d";
const scene = s => sel(s) + " .mm3d-scene";
const stateOf = (page, s) => page.$eval(sel(s), e => e.dataset.state);
const waitState = async (page, s, want, ms = 20000) => { const t = Date.now(); while (Date.now() - t < ms) { const st = await stateOf(page, s).catch(() => null); if (st === want) return true; await sleep(50); } return false; };
const cam = (page, s) => page.$eval(scene(s), e => ({ yaw: Number(e.dataset.yaw), pitch: Number(e.dataset.pitch), zoom: Number(e.dataset.zoom) }));
const probe = (page, s, fx, fy) => page.evaluate(([id, fx, fy]) => { const r = window.__mesh.renderers[id], c = document.querySelector("[data-testid=sec-" + id + "] .mm3d-canvas"); if (!r || !c) return null; return r.probe(c.clientWidth * fx, c.clientHeight * fy); }, [s, fx, fy]);
const red = p => p && p[0] > 120 && p[0] > p[2] * 1.8 && p[0] > p[1] * 1.6;
const blue = p => p && p[2] > 110 && p[2] > p[0] * 1.6;
const amber = p => p && p[0] > 170 && p[1] > 90 && p[2] < p[1] * 0.75;
const bgLike = p => p && Math.abs(p[0] - 244) < 8 && Math.abs(p[1] - 247) < 8 && Math.abs(p[2] - 251) < 8;
const center = async (page, s) => { const b = await page.locator(scene(s)).boundingBox(); return { x: b.x + b.width / 2, y: b.y + b.height / 2, b }; };

try {
  // ── desktop: rendering, depth, picking, highlight, interaction, review, errors, context loss, leaks ─────────────────────────────────
  const { page, t0 } = await open({ scale: 2 });
  const okView = await waitState(page, "view", "ready");
  check("WebGL 2 viewer reaches the ready state (asset streamed, SHA-256 verified, validated, uploaded)", okView, (Date.now() - t0) + " ms");
  await page.evaluate(() => Promise.all(Object.values(window.__mesh.renderers).filter(Boolean).map(r => r.texturesReady)));
  await sleep(200);
  const stats = await page.$eval(scene("view"), e => ({ draws: Number(e.dataset.draws), tris: Number(e.dataset.triangles), gpu: Number(e.dataset.gpuBytes), samples: Number(e.dataset.samples), dpr: Number(e.dataset.dpr) }));
  check("depth-buffered draw of all five parts with multisampling and a high-DPI buffer", stats.draws === 5 && stats.tris === 1188 && stats.samples >= 2 && stats.dpr === 2, JSON.stringify(stats));
  const cw = await page.$eval(sel("view") + " .mm3d-canvas", c => ({ w: c.width, cw: c.clientWidth }));
  check("drawing buffer = CSS size × devicePixelRatio", cw.w === cw.cw * 2, JSON.stringify(cw));
  const c0 = await probe(page, "view", 0.5, 0.5);
  check("front block (red) is drawn in front of the back plate (depth test)", red(c0), JSON.stringify(c0));
  const corner = await probe(page, "view", 0.02, 0.03);
  check("background stays clear where there is no geometry", bgLike(corner), JSON.stringify(corner));
  // texture: the checker plate shows two distinct tones along a line across it
  const tones = [];
  for (let i = 0; i < 24; i++) { const p = await probe(page, "view", 0.3 + i * 0.017, 0.78); if (p) tones.push(p[0] + p[1] + p[2]); }
  const spread = Math.max(...tones) - Math.min(...tones);
  check("base-colour texture is sampled (checker plate shows contrasting cells)", spread > 60, "luminance spread " + spread);
  // hide the front block → the back plate is visible at the same pixel
  await page.click(sel("view") + " li[data-part=frontBlock] .mm3d-hide");
  await sleep(120);
  const c1 = await probe(page, "view", 0.5, 0.5);
  check("hiding the front block reveals the back plate at the same pixel", blue(c1), JSON.stringify(c1));
  await page.click(sel("view") + " li[data-part=frontBlock] .mm3d-hide");
  await sleep(120);
  // rotate half a turn with the buttons (yaw +π): the back plate is now in front
  for (let i = 0; i < 12; i++) await page.click(sel("view") + " button[aria-label='تدوير لليمين']");
  await sleep(250);
  const yaw = (await cam(page, "view")).yaw;
  const c2 = await probe(page, "view", 0.5, 0.5);
  check("turned round (yaw ≈ π): the back plate occludes the block — true depth, not draw order", Math.abs(Math.abs(yaw) - 3) < 0.25 && blue(c2), "yaw " + yaw + " " + JSON.stringify(c2));
  await page.click(sel("view") + " button:has-text('إعادة العرض')");
  await sleep(250);
  const home = await cam(page, "view");
  check("reset returns to the authored view", Math.abs(home.yaw) < 1e-3 && Math.abs(home.pitch - 0.2) < 1e-3 && home.zoom === 1, JSON.stringify(home));
  // mouse drag rotates; Ctrl+wheel zooms
  const { x, y } = await center(page, "view");
  await page.mouse.move(x, y); await page.mouse.down(); for (let i = 1; i <= 8; i++) await page.mouse.move(x + i * 20, y + i * 4); await page.mouse.up();
  await sleep(600);
  const dragged = await cam(page, "view");
  check("mouse drag rotates the model (shared 21D orbit controller)", dragged.yaw > 0.3, JSON.stringify(dragged));
  await page.mouse.move(x, y); await page.keyboard.down("Control"); await page.mouse.wheel(0, -400); await page.keyboard.up("Control");
  await sleep(200);
  check("Ctrl + wheel zooms in", (await cam(page, "view")).zoom > 1.2, JSON.stringify(await cam(page, "view")));
  await page.focus(scene("view")); await page.keyboard.press("Home");
  await page.keyboard.press("ArrowLeft"); await sleep(100);
  check("keyboard: Home resets, arrows rotate", Math.abs((await cam(page, "view")).yaw + 0.2) < 1e-3);
  // picking + selection (front-most part), max 2, the list stays in sync
  await page.locator(sel("select")).scrollIntoViewIfNeeded();
  await waitState(page, "select", "ready");
  await sleep(150);
  const sc = await center(page, "select");
  await page.mouse.click(sc.x, sc.y);
  await sleep(200);
  check("clicking the model selects the FRONT-MOST part under the pointer (GPU pick)", (await page.textContent("[data-testid=selected]")) === "frontBlock");
  const hl = await probe(page, "select", 0.5, 0.5);
  check("the selected part is highlighted in the WebGL image", amber(hl), JSON.stringify(hl));
  await page.click(sel("select") + " li[data-part=ball] input");
  await sleep(100);
  check("the parts list selects too (accessible alternative), in authoring order", (await page.textContent("[data-testid=selected]")) === "frontBlock,ball");
  check("selection respects the maximum (third choice disabled)", await page.$eval(sel("select") + " li[data-part=rod] input", e => e.disabled));
  await page.mouse.click(sc.x, sc.y);
  await sleep(150);
  check("clicking a selected part deselects it", (await page.textContent("[data-testid=selected]")) === "ball");
  // review marks render in the image and the list
  await page.locator(sel("review")).scrollIntoViewIfNeeded();
  await waitState(page, "review", "ready");
  await sleep(150);
  const rv = await probe(page, "review", 0.5, 0.5);
  check("review marks: the correct part is tinted green", rv && rv[1] > rv[0] * 1.3 && rv[1] > rv[2] * 1.3, JSON.stringify(rv));
  check("review marks are also text in the list", (await page.$$eval(sel("review") + " .mm3d-mark", l => l.length)) === 3);
  // an upload asset (API runtime route) renders; rotate-only controls
  await page.locator(sel("upload")).scrollIntoViewIfNeeded();
  check("an uploaded asset loads from the content-addressed API route", await waitState(page, "upload", "ready"));
  check("authored controls: no zoom buttons, no hide toggles", (await page.$$(sel("upload") + " button[aria-label='تكبير']")).length === 0 && (await page.$$(sel("upload") + " .mm3d-hide")).length === 0);
  // integrity + missing parts fail closed with meaningful messages
  await page.locator(sel("integrity")).scrollIntoViewIfNeeded();
  check("substituted bytes (SHA-256 mismatch) are refused before parsing", await waitState(page, "integrity", "error") && (await page.textContent(sel("integrity") + " [role=alert]")).includes("بصمة"));
  await page.locator(sel("parts")).scrollIntoViewIfNeeded();
  check("labelled parts missing from the file need teacher review", await waitState(page, "parts", "error") && (await page.textContent(sel("parts") + " [role=alert]")).includes("مراجعة المعلم"));
  // context loss → automatic restore → the image is drawn again
  await page.locator(sel("view")).scrollIntoViewIfNeeded();
  check("a viewer scrolled away was parked (GL context released) and comes back when visible", await waitState(page, "view", "ready"));
  await page.waitForSelector(sel("view") + " .mm3d-canvas");
  await page.evaluate(() => { const c = document.querySelector("[data-testid=sec-view] .mm3d-canvas"); window.__lose = c.getContext("webgl2").getExtension("WEBGL_lose_context"); window.__lose.loseContext(); });
  const lostOk = await waitState(page, "view", "lost", 5000);
  await page.evaluate(() => window.__lose.restoreContext());
  const restored = await waitState(page, "view", "ready", 8000);
  await sleep(200);
  const c3 = await probe(page, "view", 0.5, 0.5);
  check("context loss shows a status, restores automatically and draws again", lostOk && restored && c3 && !bgLike(c3), JSON.stringify(c3));
  // 20 mount / unmount cycles: no live renderer left behind, no error
  const before = await page.evaluate(() => window.__mesh.liveCount());
  for (let i = 0; i < 20; i++) { await page.click("[data-testid=toggle-mount]"); await sleep(i % 2 ? 120 : 30); }
  await sleep(300);
  const after = await page.evaluate(() => window.__mesh.liveCount());
  check("20 mount / unmount cycles leave no live renderer behind", after === before, before + " → " + after);
  const parked = await page.evaluate(() => ({ ready: document.querySelectorAll(".mm3d[data-state=ready]").length, waiting: document.querySelectorAll(".mm3d[data-state=waiting]").length, live: window.__mesh.liveCount() }));
  check("viewers far off-screen are parked: no GL context is held for them", parked.waiting >= 1 && parked.live === parked.ready, JSON.stringify(parked));
  check("the asset is downloaded once per hash and shared between viewers (parsed-document cache)", assetRequests <= 4, assetRequests + " requests");
  check("RTL figure, LTR drawing", (await page.$eval(sel("view"), e => getComputedStyle(e).direction)) === "rtl" && (await page.$eval(sel("view") + " .mm3d-frame", e => getComputedStyle(e).direction)) === "ltr");
  await page.screenshot({ path: path.join(out, "desktop.png"), fullPage: false });
  await page.close();

  // ── several questions on one exam page: every visible viewer holds its own live context at once ─────────────────────────────────
  const tall = (await open({ width: 1280, height: 4200 })).page;
  for (const s of ["view", "select", "upload", "review"]) await waitState(tall, s, "ready");
  const many = await tall.evaluate(() => ({ ready: document.querySelectorAll(".mm3d[data-state=ready]").length, live: window.__mesh.liveCount() }));
  check("four models visible on one page render at once (four live contexts)", many.ready === 4 && many.live === 4, JSON.stringify(many));
  await tall.close();

  // ── phone: touch rotation and tap selection, no overflow ───────────────────────────────────────────────────────────────────────────
  const phone = (await open({ width: 390, height: 844, touch: true, scale: 3, query: "?only=select" })).page;
  await waitState(phone, "select", "ready");
  const pb = await center(phone, "select");
  const cdp = await phone.context().newCDPSession(phone);
  const touch = async (type, pts) => cdp.send("Input.dispatchTouchEvent", { type, touchPoints: pts.map(([px, py], id) => ({ x: px, y: py, id })) });
  await touch("touchStart", [[pb.x, pb.y]]); for (let i = 1; i <= 8; i++) await touch("touchMove", [[pb.x + i * 15, pb.y]]); await touch("touchEnd", []);
  await sleep(600);
  check("one-finger touch drag rotates on a phone", Math.abs((await cam(phone, "select")).yaw) > 0.3, JSON.stringify(await cam(phone, "select")));
  check("phone: high-DPI buffer capped at 2×", await phone.$eval(scene("select"), e => Number(e.dataset.dpr)) === 2);
  const ov = await phone.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth }));
  check("@390 px: no horizontal overflow", ov.sw <= ov.iw, JSON.stringify(ov));
  await phone.screenshot({ path: path.join(out, "phone.png") });
  await phone.close();

  // ── WebGL unavailable: the fallback keeps the parts list usable ────────────────────────────────────────────────────────────────────
  const nogl = (await open({ query: "?nowebgl=1&only=select" })).page;
  check("WebGL 2 unavailable → meaningful fallback, no error", await waitState(nogl, "select", "fallback") && (await nogl.textContent(sel("select") + " [role=note]")).includes("WebGL"));
  await nogl.click(sel("select") + " li[data-part=rod] input");
  check("…and the parts list still answers the question", (await nogl.textContent("[data-testid=selected]")) === "rod");
  await nogl.close();
  check("no page errors", errors.length === 0, errors.slice(0, 3).join(" | "));
  check("no external asset or network host", foreign.length === 0, foreign.slice(0, 3).join(" "));
} catch (e) {
  check("harness ran to completion", false, String(e && e.stack || e));
} finally {
  await browser.close();
  server.close();
}
const failed = checks.filter(c => !c.ok);
console.log(failed.length ? failed.length + " CHECK(S) FAILED" : "ALL " + checks.length + " CHECKS PASSED");
process.exit(failed.length ? 1 : 0);
